package yesman.epicfight.skill.weaponinnate;

import java.util.List;
import java.util.Map;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;
import yesman.epicfight.api.animation.types.AttackAnimation;
import yesman.epicfight.skill.weaponinnate.SimpleWeaponInnateSkill;
import yesman.epicfight.skill.weaponinnate.WeaponInnateSkill;
import yesman.epicfight.world.capabilities.entitypatch.player.PlayerPatch;
import yesman.epicfight.world.capabilities.item.CapabilityItem;

public class WrathfulLightingSkill
extends SimpleWeaponInnateSkill {
    public WrathfulLightingSkill(SimpleWeaponInnateSkill.Builder builder) {
        super(builder);
    }

    @Override
    public List<Component> getTooltipOnItem(ItemStack itemStack, CapabilityItem itemCap, PlayerPatch<?> playerpatch) {
        List<Component> list = super.getTooltipOnItem(itemStack, itemCap, playerpatch);
        this.generateTooltipforPhase(list, itemStack, itemCap, playerpatch, (Map)this.properties.get(1), "Thunder:");
        return list;
    }

    @Override
    public WeaponInnateSkill registerPropertiesToAnimation() {
        AttackAnimation anim = (AttackAnimation)this.attackAnimation.get();
        for (AttackAnimation.Phase phase : anim.phases) {
            phase.addProperties(((Map)this.properties.get(0)).entrySet());
            phase.addProperties(((Map)this.properties.get(1)).entrySet());
        }
        return this;
    }
